{
  "technical_and_design_decisions": [
    "Use Spring AMQP's RabbitAdmin or Rabbit REST API for queue/topic cleanup on stream destroy (U1).",
    "Leverage Spring Integration error channels to allow tapping into module exceptions (U2).",
    "Utilize Spring Security and Spring Boot out-of-the-box features to secure REST endpoints, including considerations for DSL shell and Admin UI (U3).",
    "Create a new MVC-aware HTTP module with embedded Tomcat to leverage spring-mvc and spring-security, rather than extending the existing HTTP source module (U5).",
    "Implement a combination of client-side polling and server-side event propagation for job and stream status changes (U6).",
    "Use Spring Integration SFTP Adapter for the new SFTP source module (U7).",
    "Use the native ElasticSearch client for the new ElasticSearch sink module (U8)."
  ],
  "assumptions": [
    "The development environment and CI/CD pipelines are already set up and configured.",
    "The development team has prior experience with Spring XD, Spring Integration, Spring AMQP, and Spring Security.",
    "Testing infrastructure for SFTP can be mocked or containerized using Docker.",
    "An ElasticSearch instance for testing is available or can be easily spun up locally.",
    "The effort for U3 includes both the research spike and the initial implementation of the security layer.",
    "Effort estimates include unit and integration testing, but exclude full system-level performance testing and production deployment."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "RabbitMQ Queue/Topic Cleanup",
      "activity_description": "Design and implement the optional '--clean' attribute for the stream destroy command to clean up associated queues/topics. Integrate with RabbitAdmin or Rabbit REST API, and handle edge cases such as producers/queues still containing data and fanout exchanges.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A2",
      "activity_name": "Module Exception Notification",
      "activity_description": "Implement the ability to tap into an error channel to receive and notify users of exceptions thrown in a module for each stream/module.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A3",
      "activity_name": "REST Endpoint Security",
      "activity_description": "Research Spring Security and Spring Boot OOTB features, design the approach for XD (credentials configuration, DSL shell, Admin UI), and implement the security layer for all listed REST endpoints.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4",
      "activity_name": "Documentation for XD Keys",
      "activity_description": "Document the available keys such as ${xd.stream.name}, ${xd.job.name}, and ${xd.container.???} that are available to users.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A5",
      "activity_name": "MVC-aware HTTP Module",
      "activity_description": "Develop an out-of-the-box MVC-aware HTTP module with embedded Tomcat to leverage spring-mvc and spring-security. Add richer content-type support and full header mapping in the source.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A6",
      "activity_name": "Client Polling and Server-side Event Propagation",
      "activity_description": "Implement a common polling strategy on the client side to detect status changes of jobs and streams. Propagate events between containers and admin-server to inform about system changes and notify connected UI clients.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A7",
      "activity_name": "SFTP Source Module",
      "activity_description": "Implement an SFTP source module using the Spring Integration SFTP Adapter to access, transfer, and manage files over reliable data streams. Set up the necessary testing infrastructure.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A8",
      "activity_name": "ElasticSearch Sink Module",
      "activity_description": "Implement a native ElasticSearch sink module to allow users to aggregate, search, and analyze data insights in real-time.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 39
  }
}

